(635, ' INSUFLADOR CON LLAVE DE PASO CON TRES VIAS , VOLUMEN DE 30 ATM\nPRODUCTO STANDARD - ESTERIL \nIMPORTADO- DEMAX  ', 'INSLUFADOR', NULL, NULL, 12, NULL, NULL),
