(638, 'KIT DE  DISPOSITIVO INTRA AORTICO PARA CIRCULACION VENTRICULAR ASISTADA CON CONTRAPULSADOR \n\nINCLUYE ALQUILER DE CONSOLA PARA PROCEDIMIENTO, INTRODUCTOR, CLAMPS DE TUBO, JERINGA DE 60ML PICO THOMEY. \n \nMODELO: iVAC 2L\nMARCA: PULSECATH \nORIGEN : HOLANDA \n\nASISTENCIA TECNICA EN IMPLANTE \n', 'iVAC 2L', NULL, NULL, 14, NULL, NULL),
